<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../Config/Database.php';$db=(new Database())->connect();
$db->exec('CREATE TABLE IF NOT EXISTS categorias_gasto (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(80) NOT NULL UNIQUE,activo TINYINT NOT NULL DEFAULT 1,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB');
$db->exec('CREATE TABLE IF NOT EXISTS gastos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,folio VARCHAR(30) NOT NULL UNIQUE,categoria_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,turno_id BIGINT UNSIGNED NULL,movimiento_id BIGINT UNSIGNED NULL UNIQUE,metodo_pago_id BIGINT UNSIGNED NOT NULL,tipo_metodo VARCHAR(20) NOT NULL,origen ENUM(\'caja\',\'externo\') NOT NULL,fecha DATE NOT NULL,monto DECIMAL(14,2) NOT NULL,cuenta VARCHAR(100) NULL,beneficiario VARCHAR(150) NULL,descripcion VARCHAR(300) NOT NULL,referencia VARCHAR(100) NULL,clave CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,huella CHAR(64) NOT NULL,datos JSON NOT NULL,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(categoria_id) REFERENCES categorias_gasto(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(turno_id) REFERENCES turnos_caja(id),FOREIGN KEY(movimiento_id) REFERENCES movimientos_efectivo(id),FOREIGN KEY(metodo_pago_id) REFERENCES metodos_pago(id),UNIQUE KEY uq_gasto_solicitud(usuario_id,clave),KEY ix_gasto_fecha(fecha),KEY ix_gasto_usuario_fecha(usuario_id,fecha),KEY ix_gasto_categoria_fecha(categoria_id,fecha),KEY ix_gasto_turno(turno_id)) ENGINE=InnoDB');
$q=$db->prepare('INSERT IGNORE INTO categorias_gasto(nombre) VALUES (?)');foreach(array('Renta','Servicios','Transporte','Insumos','Comisiones','Otros') as $name)$q->execute(array($name));
echo "Gastos y categorías preparados.",PHP_EOL;
